// Написан вручную (запасной путь: MCP-генератор не нашёл seed). Селекторы и значения сверены на живой странице через playwright-cli
// (iPhone 13 Mini, free, 2026-10-29: 158.97×36, rgba(255,255,255,0.86), blur(12px), текст rgb(34,20,31)), сам тест не прогонялся.
// spec: .qa/e2e/specs/location-map.md 2.3 · кейс .qa/tests/location-map/IND-03.md
// seed: tests/seed.free.geo.spec.ts
// В конце шаринг выключается.
import { test, expect } from '@playwright/test';
import path from 'path';
import { enableSharing, disableSharing } from './map-helpers';
import { saveSession } from '../_shared/session';

test.use({
  storageState: path.resolve(__dirname, '../../../auth/free.json'),
  viewport: { width: 390, height: 844 },
  hasTouch: true,
  geolocation: { latitude: 32.0853, longitude: 34.7818, accuracy: 10 },
  permissions: ['geolocation'],
});

const PILL = 'שיתוף מיקום פעיל';

test.describe('Индикатор шаринга местоположения', () => {
  test('Вид индикатора по Figma 869-7423 — 159×36, фон rgba(255,255,255,.86) + blur, текст #22141F @iphone @data (#5f64d4)', async ({ page }) => {
    try {
      // 1. Выключить, если включён; включить
      await disableSharing(page);
      await enableSharing(page);

      // 2. Контейнер пилюли (role=switch, у него фон) и текстовый узел внутри
      const pill = page.getByRole('switch', { name: PILL });
      await expect(pill).toBeVisible();
      const box = await pill.boundingBox();
      expect(box, 'boundingBox пилюли').not.toBeNull();
      expect(Math.abs(box!.width - 159)).toBeLessThanOrEqual(2);
      expect(Math.abs(box!.height - 36)).toBeLessThanOrEqual(2);

      const look = await pill.evaluate((el) => {
        const cs = getComputedStyle(el) as CSSStyleDeclaration & { webkitBackdropFilter?: string };
        return { bg: cs.backgroundColor, bf: cs.backdropFilter || cs.webkitBackdropFilter || '' };
      });
      const m = look.bg.match(/rgba?\(\s*(\d+),\s*(\d+),\s*(\d+)(?:,\s*([\d.]+))?\)/);
      expect(m, `background-color: ${look.bg}`).not.toBeNull();
      expect([m![1], m![2], m![3]].map(Number)).toEqual([255, 255, 255]);
      const alpha = Number(m![4] ?? 1);
      expect(alpha).toBeGreaterThanOrEqual(0.8);
      expect(alpha).toBeLessThanOrEqual(0.92);
      expect(look.bf).toContain('blur');

      await expect(pill.getByText(PILL, { exact: true })).toHaveCSS('color', 'rgb(34, 20, 31)');
    } finally {
      // 3. Очистка: шаринг → false
      await disableSharing(page).catch(() => {});
      await saveSession(page, 'free');
    }
  });
});
